input.new_string:
export const ROLE_RANK: Readonly<Record<Role, number>> = {
  owner: 4,
  admin: 3,
  member: 2,
  viewer: 1,
};

/**
 * Roles that occupy a paid seat. A `viewer` is free and is absent from this
 * list on purpose — seat checks and the stored usage counter both read it.
 */
export const BILLABLE_ROLES: readonly Role[] = ["owner", "admin", "member"];

const BILLABLE_ROLE_SET: ReadonlySet<Role> = new Set(BILLABLE_ROLES);

/** True for `owner`, `admin` and `member`; false for `viewer`. */
export function isBillableRole(role: Role): boolean {
  return BILLABLE_ROLE_SET.has(role);
}

