/** Pending invitations that have not been accepted or revoked, any role. */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(pendingInvitationPredicate(orgId))
    .get();
  return row?.value ?? 0;
}

/** Pending invitations that occupy a seat. Viewer invites are free. */
export async function countPendingBillableInvitations(
  orgId: OrgId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        pendingInvitationPredicate(orgId),
        inArray(invitations.role, [...BILLABLE_ROLES]),
      ),
    )
    .get();
  return row?.value ?? 0;
}

function pendingInvitationPredicate(orgId: OrgId) {
  return and(
    orgPredicate(invitations.orgId, orgId),
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
  );
}

