const tenant = await createTenant("invite-bulk-quota", "starter");

// Starter includes 10 seats. The tenant starts with three billable members
// (the viewer is free). Six more billable members leave a single seat.
for (let i = 0; i < 6; i += 1) {
  const user = await userRepo.insertUser({
    email: `filler${i}@invite-bulk-quota.test`,
    name: `Filler ${i}`,
    passwordHash: "seed",
  });
  await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
}
await expect(
  memberRepo.countBillableActiveMembers(tenant.org.id),
).resolves.toBe(9);

// A viewer-only batch takes no seats, so a full plan still accepts it.
it("allows viewer invites when the seat quota is already full", async () => {
  const tenant = await createTenant("invite-viewer-free", "free");

  await expect(
    invitationService.inviteMembers(tenant.actors.admin, {
      orgId: tenant.org.id,
      invites: [
        { email: "v1@invite-viewer-free.test", role: "viewer" },
        { email: "v2@invite-viewer-free.test", role: "viewer" },
      ],
    }),
  ).resolves.toHaveLength(2);

  await expect(
    invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "extra@invite-viewer-free.test",
      role: "member",
    }),
  ).rejects.toThrow(/seats/);
});

// One billable invite over the line refuses the whole batch, viewers included.
it("refuses a mixed batch that asks for more seats than remain", async () => {
  const tenant = await createTenant("invite-mixed-batch", "free");

  await expect(
    invitationService.inviteMembers(tenant.actors.admin, {
      orgId: tenant.org.id,
      invites: [
        { email: "viewer@invite-mixed-batch.test", role: "viewer" },
        { email: "member@invite-mixed-batch.test", role: "member" },
      ],
