 * that asks for more billable seats than remain fails entirely rather than
 * half-succeeding. Viewer invites take no seats, so a viewer-only batch is
 * never refused by the quota. The rate limit is still charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
50→  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
60→  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const requested = input.invites.filter((invite) =>
    isBillableRole(invite.role),
  ).length;
  await assertSeatsAvailable(input.orgId, requested);
70→
  const invitations: Invitation[] = [];

