/**
 * Bulk invite. The seat quota is checked once for the whole batch — a batch
 * that asks for more billable seats than remain fails entirely rather than
 * half-succeeding. Viewer invites take no seats, so a viewer-only batch is
 * never refused by the quota. The rate limit is still charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const requested = input.invites.filter((invite) =>
    isBillableRole(invite.role),
  ).length;
  await assertSeatsAvailable(input.orgId, requested);

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const existing = await memberRepo.findMember(invitation.orgId, userId);
  if (existing) return existing;

  const member = await memberRepo.insertMember(
    invitation.orgId,
    userId,
    invitation.role,
    invitation.invitedBy,
  );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    toIsoTimestamp(new Date()),
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

/**
 * Seats currently spoken for: billable active members plus pending invitations
 * for a billable role. Accepted and revoked invitations do not count, and
 * viewer invitations never do.
 */
export async function countOccupiedSeats(orgId: OrgId): Promise<number> {
  const [active, pending] = await Promise.all([
    memberRepo.countBillableActiveMembers(orgId),
    invitationRepo.countPendingBillableInvitations(orgId),
  ]);
  return active + pending;
}

/**
 * Refuses when `requested` additional billable seats would pass the plan quota.
 * A request of zero (a viewer-only change) is never refused, even if the plan
 * is already full.
 */
export async function assertSeatsAvailable(
  orgId: OrgId,
  requested: number,
): Promise<void> {
  if (requested <= 0) return;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const seatsUsed = await countOccupiedSeats(orgId);

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, requested)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }
}

